<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { opcApi } from '@/api/opc'
type Doc={id:string;name:string;category:string;source_uri:string;content:string;chunk_count:number;status:string;updated_at:string}
const useMock=import.meta.env.VITE_USE_MOCK==='true';const search=ref('');const category=ref('');const dialog=ref(false);const detailDialog=ref(false);const editingId=ref('');const selected=ref<Doc|null>(null)
const categories=['产品规格','材料价格','工艺标准','质量标准','包装物流','工厂能力']
const docs=ref<Doc[]>([
  {id:'k1',name:'建筑防护网常用规格与核价规则',category:'产品规格',source_uri:'internal://specs/building-mesh',content:'建筑防护网常用丝径、网孔、表面处理和重量计算规则。',chunk_count:38,status:'ACTIVE',updated_at:'今天 09:30'},
  {id:'k2',name:'低碳钢丝与镀锌丝材料价格表',category:'材料价格',source_uri:'internal://prices/steel-wire',content:'材料价格由管理员维护，报价引擎仅读取已发布版本。',chunk_count:24,status:'ACTIVE',updated_at:'昨天 17:20'},
  {id:'k3',name:'出口丝网包装与装柜规范',category:'包装物流',source_uri:'internal://packing/export',content:'托盘、缠膜、防潮、唛头和装柜要求。',chunk_count:17,status:'ACTIVE',updated_at:'09-20'},
  {id:'k4',name:'合作工厂设备及工艺能力表',category:'工厂能力',source_uri:'internal://factory/capability',content:'工厂设备、工艺、资质、交期和质量评分。',chunk_count:31,status:'REVIEW',updated_at:'09-18'},
])
const form=reactive({name:'',category:'产品规格',source_uri:'',content:'',chunk_count:0,status:'ACTIVE'})
const filtered=computed(()=>docs.value.filter(x=>(!search.value||`${x.name}${x.content}`.toLowerCase().includes(search.value.toLowerCase()))&&(!category.value||x.category===category.value)))
onMounted(async()=>{if(useMock)return;try{const{data}=await opcApi.listKnowledge();docs.value=data.map((x:any)=>({...x,updated_at:x.updated_at?.slice(0,16)||''}))}catch{ElMessage.warning('知识库加载失败，已保留演示数据')}})
function reset(){Object.assign(form,{name:'',category:'产品规格',source_uri:'',content:'',chunk_count:0,status:'ACTIVE'})}
function openCreate(){editingId.value='';reset();dialog.value=true}
function openEdit(x:Doc){editingId.value=x.id;Object.assign(form,x);dialog.value=true}
function openDetail(x:Doc){selected.value=x;detailDialog.value=true}
async function save(){if(!form.name||!form.content)return ElMessage.warning('请填写资料名称和内容');const payload={...form};let id=editingId.value;if(id){if(!useMock)await opcApi.updateKnowledge(id,payload);const x=docs.value.find(x=>x.id===id);if(x)Object.assign(x,payload,{updated_at:'刚刚'})}else{id=useMock?`k-${Date.now()}`:(await opcApi.createKnowledge(payload)).data.id;docs.value.unshift({id,...payload,updated_at:'刚刚'})}if(!useMock)await opcApi.indexKnowledge(id);dialog.value=false;ElMessage.success('知识资料已保存并建立索引')}
async function remove(x:Doc){await ElMessageBox.confirm(`确认删除“${x.name}”？`,'删除资料',{type:'warning'});if(!useMock)await opcApi.deleteKnowledge(x.id);docs.value=docs.value.filter(i=>i.id!==x.id);ElMessage.success('资料已删除')}
function publish(x:Doc){x.status=x.status==='ACTIVE'?'REVIEW':'ACTIVE';ElMessage.success(x.status==='ACTIVE'?'资料已发布':'资料已转为待复核')}
defineExpose({openCreate})
</script>
<template><div class="layout"><aside class="side card"><h3>知识分类</h3><button :class="{active:!category}" @click="category=''">全部资料 <b>{{ docs.length }}</b></button><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{ c }} <b>{{ docs.filter(x=>x.category===c).length }}</b></button><div class="health"><span>知识库健康度</span><strong>{{ Math.round(docs.filter(x=>x.status==='ACTIVE').length/docs.length*100) }}%</strong><i><em :style="{width:Math.round(docs.filter(x=>x.status==='ACTIVE').length/docs.length*100)+'%'}"></em></i><small>{{ docs.filter(x=>x.status!=='ACTIVE').length }} 份资料需要复核</small></div></aside><section class="card main"><header><h3>知识资料</h3><div><el-input v-model="search" placeholder="搜索资料内容" :prefix-icon="'Search'" clearable/><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>导入资料</el-button></div></header><div class="doc" v-for="x in filtered" :key="x.id"><i><el-icon><Document/></el-icon></i><div><b>{{ x.name }}</b><span>{{ x.category }} · {{ x.chunk_count }} 个知识片段 · {{ x.updated_at }}</span></div><em :class="x.status">{{ x.status==='ACTIVE'?'已生效':'待复核' }}</em><div><button @click="openDetail(x)">查看</button><button @click="publish(x)">{{ x.status==='ACTIVE'?'撤回':'发布' }}</button><button @click="openEdit(x)">编辑</button><button class="danger" @click="remove(x)">删除</button></div></div></section>
<el-dialog v-model="dialog" :title="editingId?'编辑知识资料':'导入知识资料'" width="680px"><el-form label-position="top"><div class="form-grid"><el-form-item label="资料名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="分类"><el-select v-model="form.category"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select></el-form-item><el-form-item label="来源链接/文件标识" class="wide"><el-input v-model="form.source_uri"/></el-form-item><el-form-item label="知识内容" class="wide"><el-input v-model="form.content" type="textarea" :rows="8"/></el-form-item><el-form-item label="知识片段数"><el-input-number v-model="form.chunk_count" :min="0"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="已生效" value="ACTIVE"/><el-option label="待复核" value="REVIEW"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存并索引</el-button></template></el-dialog>
<el-dialog v-model="detailDialog" title="知识资料详情" width="650px"><div v-if="selected" class="detail"><h3>{{ selected.name }}</h3><p><b>分类：</b>{{ selected.category }}　<b>片段：</b>{{ selected.chunk_count }}　<b>状态：</b>{{ selected.status }}</p><article>{{ selected.content }}</article><small>{{ selected.source_uri }}</small></div><template #footer><el-button @click="detailDialog=false">关闭</el-button><el-button type="primary" @click="selected&&openEdit(selected);detailDialog=false">编辑</el-button></template></el-dialog>
</div></template>
<style scoped>
.layout{display:grid;grid-template-columns:230px 1fr;gap:18px}.card{background:#fff;border:1px solid #e2eaf2;border-radius:12px;box-shadow:0 5px 18px rgba(23,47,79,.045)}.side{padding:17px}.side h3,.main h3{margin:0 0 13px;font-size:15px}.side>button{width:100%;height:38px;border:0;background:transparent;color:#687a90;border-radius:7px;display:flex;align-items:center;padding:0 9px;font-size:10px;cursor:pointer}.side button b{margin-left:auto}.side button.active{background:#eaf2ff;color:#286fd2}.health{border-top:1px solid #e8edf3;margin-top:14px;padding-top:15px}.health span,.health strong{font-size:9px}.health strong{float:right}.health>i{display:block;height:6px;background:#edf2f6;border-radius:3px;margin:8px 0;overflow:hidden}.health>i em{display:block;height:100%;background:#20ad84}.health small{color:#9aa5b2;font-size:8px}.main{padding:18px}.main>header{display:flex;justify-content:space-between;align-items:center}.main header>div{display:flex;gap:8px}.main header .el-input{width:240px}.doc{display:grid;grid-template-columns:38px 1fr auto 170px;gap:10px;align-items:center;min-height:63px;border-top:1px solid #edf1f5}.doc>i{width:34px;height:34px;display:grid;place-items:center;border-radius:8px;background:#eaf2ff;color:#2d73d4}.doc b,.doc span{display:block}.doc b{font-size:10px}.doc span{color:#98a3b1;font-size:8px;margin-top:4px}.doc>em{font-style:normal;font-size:8px;padding:4px 7px;border-radius:10px}.doc>em.ACTIVE{color:#168261;background:#e7f8f1}.doc>em.REVIEW{color:#c1721c;background:#fff1db}.doc>div:last-child{display:flex;gap:3px}.doc button{border:0;background:#edf4ff;color:#286ed0;border-radius:4px;padding:5px 6px;font-size:8px;cursor:pointer}.doc button.danger{background:#fff0ef;color:#d65b4c}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .wide{grid-column:1/-1}.form-grid .el-select,.form-grid .el-input-number{width:100%}.detail p,.detail article,.detail small{font-size:10px;color:#66788d}.detail article{background:#f6f8fb;border-radius:8px;padding:14px;line-height:1.8;margin:12px 0}@media(max-width:800px){.layout{grid-template-columns:1fr}.doc{grid-template-columns:38px 1fr auto}.doc>div:last-child{grid-column:2/-1}.form-grid{grid-template-columns:1fr}}
</style>
